CREATE TABLE IF NOT EXISTS roles (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash TEXT NOT NULL, role_id BIGINT REFERENCES roles(id), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS categories (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, slug VARCHAR(100) NOT NULL UNIQUE, name_bn VARCHAR(160) NOT NULL, name_en VARCHAR(160) NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS tools (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, category_id BIGINT REFERENCES categories(id), slug VARCHAR(120) NOT NULL UNIQUE, name_bn VARCHAR(180) NOT NULL, name_en VARCHAR(180) NOT NULL, description_bn TEXT, description_en TEXT, execution_type VARCHAR(20) NOT NULL DEFAULT 'client' CHECK (execution_type IN ('client','server','api')), version VARCHAR(30) NOT NULL DEFAULT '1.0.0', is_active BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS favorites (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, tool_id BIGINT NOT NULL REFERENCES tools(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (user_id, tool_id));
CREATE TABLE IF NOT EXISTS usage_history (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id BIGINT REFERENCES users(id) ON DELETE SET NULL, tool_id BIGINT NOT NULL REFERENCES tools(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_tools_category_active ON tools(category_id, is_active);
CREATE INDEX IF NOT EXISTS idx_usage_tool_created ON usage_history(tool_id, created_at);